/* ROLE_SONG_CLEAR_OUTPUT_CHOICE_V1：输出清唱与输入已是纯人声必须分清。 */
//@@ web
function musicSongOwnerFields(prefix,s){s=s||{};const role=!!s.roleSongOwner||!s.id&&(S.music||{}).libraryTab==='role',cid=s.roleSongOwner||musicLibraryRoleId(),roles=(S.contacts||[]).filter(c=>c&&!c.deleted);return `<div class="field"><label>添加到</label><select id="${prefix}_owner" onchange="musicSongOwnerChanged('${prefix}')"><option value="mine" ${role?'':'selected'}>我的歌单</option><option value="role" ${role?'selected':''}>他的歌单</option></select></div><div id="${prefix}_role_fields" style="display:${role?'block':'none'}"><div class="field"><label>演唱角色</label><select id="${prefix}_role">${roles.length?roles.map(c=>`<option value="${esc(c.id)}" ${String(c.id)===String(cid)?'selected':''}>${esc(c.remark||c.name)}</option>`).join(''):'<option value="">请先添加角色</option>'}</select></div><div class="field"><label>音频内容</label><select id="${prefix}_ready"><option value="source" ${s.roleSongReady===true||!s.id?'':'selected'}>原曲（请先在外部制作演唱）</option><option value="performance" ${s.roleSongReady===true||!s.id?'selected':''}>已经是他的演唱</option></select></div><input type="hidden" id="${prefix}_accompaniment" value="${s.roleSongHasAccompaniment===false?'vocals':'mixed'}"><div class="field"><label>其他歌名 / 别名（选填）</label><input id="${prefix}_aliases" value="${esc((s.roleSongAliases||[]).join('、'))}" placeholder="例如：Twinkle Twinkle Little Star"></div><div class="field"><label>适合什么时候唱（选填）</label><input id="${prefix}_mood" value="${esc(s.roleSongMood||'')}" placeholder="例如：哄睡、安慰、轻快"></div><div class="hint" style="margin-bottom:12px">请先在外部翻唱工具做好演唱，下载音频后导入；微信和通话会播放你保存的演唱原音。</div></div>`;}
//@@ private
function musicSongOwnerFields(prefix,s){s=s||{};const role=!!s.roleSongOwner||!s.id&&(S.music||{}).libraryTab==='role',cid=s.roleSongOwner||musicLibraryRoleId(),roles=(S.contacts||[]).filter(c=>c&&!c.deleted);return `<div class="field"><label>添加到</label><select id="${prefix}_owner" onchange="musicSongOwnerChanged('${prefix}')"><option value="mine" ${role?'':'selected'}>我的歌单</option><option value="role" ${role?'selected':''}>他的歌单</option></select></div><div id="${prefix}_role_fields" style="display:${role?'block':'none'}"><div class="field"><label>演唱角色</label><select id="${prefix}_role">${roles.length?roles.map(c=>`<option value="${esc(c.id)}" ${String(c.id)===String(cid)?'selected':''}>${esc(c.remark||c.name)}</option>`).join(''):'<option value="">请先添加角色</option>'}</select></div><div class="field"><label>音频内容</label><select id="${prefix}_ready"><option value="source" ${s.roleSongReady===true?'':'selected'}>原曲，等待转换</option><option value="performance" ${s.roleSongReady===true?'selected':''}>已经是他的演唱</option></select></div><div class="field"><label>转换方式</label><select id="${prefix}_accompaniment"><option value="mixed" ${s.roleSongHasAccompaniment===false?'':'selected'}>生成清唱（先去除背景音乐）</option><option value="vocals" ${s.roleSongHasAccompaniment===false?'selected':''}>音源已是纯人声（无需分离）</option></select></div><div class="field"><label>其他歌名 / 别名（选填）</label><input id="${prefix}_aliases" value="${esc((s.roleSongAliases||[]).join('、'))}" placeholder="例如：Twinkle Twinkle Little Star"></div><div class="field"><label>适合什么时候唱（选填）</label><input id="${prefix}_mood" value="${esc(s.roleSongMood||'')}" placeholder="例如：哄睡、安慰、轻快"></div><div class="hint" style="margin-bottom:12px">已完成的演唱会原样用于微信和通话；原曲只有手动点制作才转换。</div></div>`;}
//@@ end
function musicSongOwnerChanged(prefix){const box=document.getElementById(prefix+'_role_fields'),select=document.getElementById(prefix+'_owner');if(box&&select)box.style.display=select.value==='role'?'block':'none';}
function musicSongOwnerRead(prefix){const owner=document.getElementById(prefix+'_owner');if(!owner)return {};if(owner.value!=='role')return {roleSongOwner:'',roleSongReady:false,roleSongAliases:[],roleSongMood:''};const cid=(document.getElementById(prefix+'_role')||{}).value||'';if(!(S.contacts||[]).some(c=>c&&!c.deleted&&String(c.id)===String(cid))){toast('先选择演唱的角色');return null;}return {roleSongOwner:cid,roleSongHasAccompaniment:(document.getElementById(prefix+'_accompaniment')||{}).value!=='vocals',roleSongReady:(document.getElementById(prefix+'_ready')||{}).value==='performance',roleSongAliases:String((document.getElementById(prefix+'_aliases')||{}).value||'').split(/[、,，\n]+/).map(x=>x.trim()).filter(Boolean).slice(0,12),roleSongMood:String((document.getElementById(prefix+'_mood')||{}).value||'').trim().slice(0,120)};}
//@@ web
function musicSongSourceLabel(s,fallback){if(s.mcpAccount)return s.preview?'MCP · 试听片段':'MCP · 在线音源';return s.roleSongOwner?(s.roleSongReady===true?'他的演唱':'原曲 · 未制作演唱'):fallback;}
//@@ private
function musicSongSourceLabel(s,fallback){if(s.mcpAccount)return s.preview?'MCP · 试听片段':'MCP · 在线音源';return s.roleSongOwner?(s.roleSongReady===true?'他的演唱':'原曲 · 待转换'):fallback;}
//@@ end
/* ROLE_SONG_CLOUD_V1：每个角色单独配置；任务及密钥不进入音乐导出包。 */
function roleSongCloudConfig(cid){const cfg=S.settings&&S.settings.roleSongCloud&&S.settings.roleSongCloud[cid];return cfg&&cfg.url&&cfg.key?cfg:null;}
/* ROLE_SONG_QUOTA_VIEW_V1：只展示服务真实时长配额，不当成平台余额；旧服务保持可用。 */
function roleSongQuotaText(info){
  if(!info||info.unit!=='audio_seconds'||!/^\d{4}-\d{2}$/.test(String(info.period||'')))return '';
  const names=['limit','used','reserved','remaining'];if(names.some(k=>!Number.isSafeInteger(info[k])||info[k]<0))return '';
  if(info.used+info.reserved>Number.MAX_SAFE_INTEGER||info.remaining!==Math.max(0,info.limit-info.used-info.reserved))return '';
  const time=n=>Math.floor(n/60)+'分'+String(n%60).padStart(2,'0')+'秒';
  return info.period+'（UTC月）\n剩余 '+time(info.remaining)+' / 限额 '+time(info.limit)+'\n已用 '+time(info.used)+' · 制作中预占 '+time(info.reserved)+'\n这是时长配额，不是云平台账户余额。实际费用请查看云平台账单。';
}
